    let html = textEl.innerHTML.replace(/&nbsp;/g, " ").replace(/<br\s*[\/]?>/gi, "\n");
    const lines = html.split("\n").map(l => l.replace(/\r/g, ""));
    while (lines.length > 0 && lines[0].trim() === "") lines.shift();
    while (lines.length > 0 && lines[lines.length - 1].trim() === "") lines.pop();
    if (lines.length === 0) return null;

    const maxLen = Math.max(...lines.map(l => l.length));
    const fullGrid = lines.map(line => {
      let r = "";
      for (let i = 0; i < maxLen; i++) {
        r += (line[i] && /[oO0]/.test(line[i])) ? "1" : "0";
      }
      return r;
    });

    const segments = [];
    let inChar = false, start = 0;
    for (let c = 0; c < maxLen; c++) {
      const hasBit = fullGrid.some(row => row[c] === "1");
      if (hasBit && !inChar) {
        inChar = true;
        start = c;
      } else if (!hasBit && inChar) {
        inChar = false;
        segments.push({ start, end: c });
      }
    }
    if (inChar) segments.push({ start, end: maxLen });

    let ketQua = "";
    segments.forEach(seg => {
      const rawCharGrid = fullGrid.map(row => row.substring(seg.start, seg.end));
      const croppedGrid = trim2DGrid(rawCharGrid);
      let bestChar = "?", highestScore = -1;

      for (const tpl of TEMPLATES) {
        const score = calculate2DSimilarity(croppedGrid, tpl.grid);
        if (score > highestScore) {
          highestScore = score;
          bestChar = tpl.char;
        }
      }

      const h = croppedGrid.length;
      if ((bestChar === "S" || bestChar === "5") && croppedGrid[0]) {
        bestChar = croppedGrid[0].startsWith("1111") ? "5" : "S";
      }
      if (bestChar === "I" || bestChar === "L" || bestChar === "1") {
        if (croppedGrid[0] && croppedGrid[h - 1]) {
          const topW = croppedGrid[0].replace(/0/g, "").length;
          const botW = croppedGrid[h - 1].replace(/0/g, "").length;
          if (topW >= 4 && botW >= 4) bestChar = "I";
          else if (topW <= 2 && botW >= 4) bestChar = "L";
          else if (topW <= 3 && botW <= 3) bestChar = "1";
        }
      }
      ketQua += bestChar;
    });

    return ketQua.length === 4 ? ketQua : null;
  }

  // Ép gán giá trị và phát đầy đủ sự kiện DOM
  function setInputValue(input, val) {
    if (!input) return;
    input.focus();
    input.value = val;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    input.dispatchEvent(new KeyboardEvent("keyup", { bubbles: true }));
  }

  // Làm sạch hoàn toàn trường văn bản (xóa sạch autofill của trình duyệt)
  function clearInputValue(input) {
    if (!input) return;
    input.value = "";
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }

  function kichHoatNutDangNhap() {
    setTimeout(() => {
      const loginBtn = document.querySelector(CONFIG.loginBtnSelector);
      if (loginBtn) {
        loginBtn.click();
        loginBtn.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
      }
    }, 120);
  }

  // ================= TỰ ĐỘNG ĐĂNG NHẬP NGẦM =================
  function lamSachVaDangNhapNgam() {
    if (!window.location.pathname.includes(CONFIG.loginPath)) return;

    const userEl = document.querySelector(CONFIG.usernameSelector);
    const passEl = document.querySelector(CONFIG.passwordSelector);
    const captchaInputEl = document.querySelector(CONFIG.captchaInputSelector);
    const textEl = document.querySelector(CONFIG.captchaTextSelector);
    const reloadTarget = document.querySelector(CONFIG.captchaReloadSelector);

    // 1. Ép làm sạch toàn bộ các trường để triệt tiêu thông tin autofill của user khác
    clearInputValue(userEl);
    clearInputValue(passEl);
    clearInputValue(captchaInputEl);

    // 2. Điền chính xác tài khoản pdhuy và mật khẩu
    setInputValue(userEl, CONFIG.username);
    setInputValue(passEl, CONFIG.password);

    // 3. Nếu không có phần tử Captcha để làm mới, giải trực tiếp mã hiện có
    if (!reloadTarget || !textEl) {
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
      return;
    }

    const oldContent = textEl.innerHTML;
    let daXuLy = false;

    const tiepTucDangNhap = () => {
      if (daXuLy) return;
      daXuLy = true;
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
    };

    // Lắng nghe khoảnh khắc CAPTCHA mới nạp xong
    const observer = new MutationObserver(() => {
      if (textEl.innerHTML !== oldContent && textEl.innerHTML.includes("ooo")) {
        observer.disconnect();
        tiepTucDangNhap();
      }
    });

    observer.observe(textEl, { childList: true, subtree: true, characterData: true });

    setTimeout(() => {
      observer.disconnect();
      tiepTucDangNhap();
    }, 350);

    // Kích hoạt sinh CAPTCHA mới
    reloadTarget.click();
    reloadTarget.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
  }

  // ================= TỰ ĐỘNG ĐĂNG XUẤT =================
  function thucHienDangXuat() {
    const userProfileEl = document.querySelector(CONFIG.userProfileSelector);
    const currentUser = userProfileEl ? userProfileEl.textContent.replace(/\s+/g, " ").trim() : "";

    // KHÓA CHẶT: Chỉ được phép đăng xuất nếu đúng tài khoản Phan Đình Huy
    if (!currentUser.includes(CONFIG.validUserName)) {
      return;
    }

    const logoutBtn = document.querySelector(CONFIG.logoutBtnSelector);
    if (logoutBtn) {
      const onclickAttr = logoutBtn.getAttribute("onclick");
      if (onclickAttr) {
        try {
          new Function(onclickAttr)();
          return;
        } catch (_) {}
      }
      logoutBtn.click();
      logoutBtn.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
    }
  }

  // ================= LẮNG NGHE PHÍM TẮT (CAPTURE PHASE) =================
  window.addEventListener("keydown", function (e) {
    if (!e.altKey || !e.shiftKey) return;

    // --- 1. Alt + Shift + I -> Làm sạch & Đăng nhập ngầm ---
    if (e.key === "I" || e.key === "i" || e.code === "KeyI") {
      if (window.location.pathname.includes(CONFIG.loginPath)) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        if (document.activeElement && typeof document.activeElement.blur === "function") {
          document.activeElement.blur();
        }

        lamSachVaDangNhapNgam();
      }
      return;
    }

    // --- 2. Alt + Shift + O -> Đăng xuất có kiểm soát ---
    if (e.key === "O" || e.key === "o" || e.code === "KeyO") {
      const userProfileEl = document.querySelector(CONFIG.userProfileSelector);
      const currentUser = userProfileEl ? userProfileEl.textContent.replace(/\s+/g, " ").trim() : "";

      // Nếu KHÔNG PHẢI Phan Đình Huy, bỏ qua toàn bộ (không can thiệp phím, không đăng xuất)
      if (!currentUser.includes(CONFIG.validUserName)) {
        return;
      }

      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      if (document.activeElement && typeof document.activeElement.blur === "function") {
        document.activeElement.blur();
      }

      thucHienDangXuat();
      return;
    }
  }, true);

})();

