    // 1. Cấu hình cơ sở dữ liệu Firebase
    const DB_BASE_URL = 'https://follow-9512b-default-rtdb.asia-southeast1.firebasedatabase.app';
    const DB_SECRET = 'T7IawhxyD0KHQ3iY1OscMT5u4FI3auxC89XC89Dj';

    // Định danh grid mục tiêu duy nhất
    const TARGET_GRID_ID = 'list_benhnhan';
    const NAME_COL_INDEX = 6;
