    // Biểu tượng Ngôi sao SVG chuẩn Tailwind Heroicons (Solid)
    const HEROICON_STAR = `
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">
      <path fill-rule="evenodd" d="M10.788 3.21c.448-1.077 1.976-1.077 2.424 0l2.082 5.006 5.404.434c1.164.093 1.636 1.545.749 2.305l-4.117 3.527 1.257 5.273c.271 1.136-.964 2.033-1.96 1.425L12 18.354 7.373 21.18c-.996.608-2.231-.29-1.96-1.425l1.257-5.273-4.117-3.527c-.887-.76-.415-2.212.749-2.305l5.404-.434 2.082-5.005Z" clip-rule="evenodd" />
    </svg>
    `;

    let currentUser = null;
    let currentUserKey = null;
    let firebaseEndpoint = null;
    let cachedFollowedList = [];
    let isFeatureEnabled = true;
    let isFirebaseConnected = false;
    let currentCalculatedWidth = 0;
    let observer = null;
    let resizeDebounce = null;

    // 2. Chuẩn hóa họ tên thành slug định danh Firebase
    function toSlug(str) {
        if (!str) return '';
        return str
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[đĐ]/g, 'd')
            .toLowerCase()
            .replace(/[^a-z0-9]/g, '')
            .trim();
    }

    // 3. Quét thông tin người dùng từ thẻ <a class="mau"> (hỗ trợ cả iframe và window.top)
    function detectCurrentUser() {
        const checkDoc = (doc) => {
            try {
                if (!doc) return null;
                const el = doc.querySelector('a.mau');
                if (el) {
                    const name = (el.innerText || el.textContent || '').trim();
                    if (name.length > 1) return name;
                }
            } catch (e) {}
            return null;
        };

        let foundName = checkDoc(document);
        if (!foundName) {
            try { if (window.top) foundName = checkDoc(window.top.document); } catch (e) {}
        }
        if (!foundName) {
            try { if (window.parent) foundName = checkDoc(window.parent.document); } catch (e) {}
        }

        return foundName;
    }

    // 4. BƯỚC ĐẦU TIÊN: Kiểm tra trạng thái trên Firebase trước khi thực thi
    const authWatcher = setInterval(async () => {
        const detectedName = detectCurrentUser();
        if (detectedName) {
            clearInterval(authWatcher);
            currentUser = detectedName;
            currentUserKey = toSlug(detectedName);
            firebaseEndpoint = `${DB_BASE_URL}/users/${currentUserKey}.json?auth=${DB_SECRET}`;

            await checkStateAndInit();
        }
    }, 500);

    setTimeout(() => clearInterval(authWatcher), 30000);

    async function checkStateAndInit() {
        try {
            const res = await fetch(firebaseEndpoint);
            if (res.ok) {
                const data = await res.json();
                isFirebaseConnected = true;

                if (data && typeof data === 'object') {
                    if (Array.isArray(data)) {
                        cachedFollowedList = data;
                        isFeatureEnabled = true;
                    } else {
                        isFeatureEnabled = (data.enabled !== undefined) ? (data.enabled === true) : true;
                        cachedFollowedList = Array.isArray(data.followed_patients) ? data.followed_patients : [];
                    }
                } else {
                    isFeatureEnabled = true;
                    cachedFollowedList = [];
                }
            } else {
                isFirebaseConnected = false;
                isFeatureEnabled = true;
            }
        } catch (err) {
            console.warn(`Lỗi nạp trạng thái ban đầu của User: ${currentUser}:`, err);
            isFirebaseConnected = false;
            isFeatureEnabled = true;
